30	/**
31	 * A customer as they stand at one point in a scenario: who they are, plus what
32	 * they have already been quoted. `quotesSoFar` counts *quotes priced*, not
33	 * steps taken — once claim steps exist the two will differ, and it is the quote
34	 * count that decides whether a policy is a follow-up contract.
35	 */
36	interface CustomerStanding {
37	  readonly customer: Customer;
38	  readonly quotesSoFar: number;
39	}
40	
41	const PROCESSING_FEE = 5;
42	
43	/**
44	 * The spec keeps intermediate amounts as exact fractions and rounds only the
45	 * final amount. Binary floating point cannot do that: `100 * 1.1` is
46	 * 110.00000000000001, which rounds *up* to 111 instead of 110.
47	 *
48	 * So percentages are applied as integer rationals — multiply by the numerator
49	 * first, divide by the denominator last — and money is carried in hundredths
50	 * of a G. Both operands of every product stay integral, so no drift accrues.
51	 */
52	const SUBUNITS_PER_G = 100;
53	const toSubunits = (gold: number): number => Math.round(gold * SUBUNITS_PER_G);
54	
55	/**
56	 * A modifier as an exact rational: the surcharge or discount *itself*, not the
57	 * multiplied total. +10 % is { num: 10, den: 100 }; a discount has a negative
58	 * numerator. Modifiers are summed onto a base, never multiplied through it.
59	 */
60	interface Rate {
61	  num: number;
62	  den: number;
63	}
64	
65	const FIRST_INSURANCE_SURCHARGE: Rate = { num: 10, den: 100 };
66	const CURSE_SURCHARGE: Rate = { num: 50, den: 100 };
67	const HIGH_ENCHANTMENT_SURCHARGE: Rate = { num: 30, den: 100 };
68	
69	const LOYALTY_DISCOUNT: Rate = { num: -20, den: 100 };
70	const FOLLOW_UP_DISCOUNT: Rate = { num: -15, den: 100 };
71	
72	/** An item is highly enchanted from this level upwards. */
73	const HIGH_ENCHANTMENT_LEVEL = 5;
74	
75	/** A customer is long-standing from this many years of business upwards. */
76	const LOYALTY_YEARS = 2;
77	
78	/** The modifier amount `rate` contributes against `subunits` — not the total. */
79	const rateAmount = (subunits: number, rate: Rate): number => (subunits * rate.num) / rate.den;
80	
81	/** Premiums round up — in the MHPCO's favour. */
82	const toPremiumGold = (subunits: number): number => Math.ceil(subunits / SUBUNITS_PER_G);
83	
84	const BASE_PREMIUM_BY_ITEM_TYPE: Record<string, number> = {
85	  sword: 100,
86	  amulet: 60,
87	  staff: 80,
88	  potion: 40,
89	  rune: 25,
90	  moonstone: 25,
91	};
92	
93	const basePremiumOf = (item: Item): number => BASE_PREMIUM_BY_ITEM_TYPE[item.type] ?? 0;
94	
95	const COMPONENT_TYPES = ["rune", "moonstone"];
96	
97	const isComponent = (item: Item): boolean => COMPONENT_TYPES.includes(item.type);
98	
99	/** Exactly this many alike components form a block, priced as one unit. */
100	const COMPONENT_BLOCK_SIZE = 3;
101	const COMPONENT_BLOCK_PREMIUM = 60;
102	
103	/** Splits items into those matching the predicate and those that do not. */
104	const partition = (items: Item[], matches: (item: Item) => boolean): [Item[], Item[]] => [
105	  items.filter(matches),
106	  items.filter((item) => !matches(item)),
107	];
108	
109	const groupByType = (items: Item[]): Map<string, Item[]> => {
110	  const groups = new Map<string, Item[]>();
111	  for (const item of items) groups.set(item.type, [...(groups.get(item.type) ?? []), item]);
112	
113	  return groups;
114	};
115	
116	const sumOfBasePremiums = (items: Item[]): number =>
117	  items.reduce((total, item) => total + basePremiumOf(item), 0);
118	
119	/**
120	 * Alike components — those of the very same type — form a block when there are
121	 * exactly COMPONENT_BLOCK_SIZE of them; the block is priced as one unit.
122	 * Any other count is priced per component.
123	 */
124	const componentGroupPremium = (group: Item[]): number =>
125	  group.length === COMPONENT_BLOCK_SIZE ? COMPONENT_BLOCK_PREMIUM : sumOfBasePremiums(group);
126	
127	/**
128	 * The policy base premium: every insured item's base premium, summed — except
129	 * that each group of alike components is priced as blocks where it can be.
130	 */
131	const policyBasePremiumOf = (items: Item[]): number => {
132	  const [components, mainItems] = partition(items, isComponent);
133	  const componentsTotal = [...groupByType(components).values()].reduce(
134	    (total, group) => total + componentGroupPremium(group),
135	    0,
136	  );
137	
138	  return sumOfBasePremiums(mainItems) + componentsTotal;
139	};
140	
141	/** The total the given rates contribute against a shared base. */
142	const sumOfRateAmounts = (base: number, rates: Rate[]): number =>
143	  rates.reduce((total, rate) => total + rateAmount(base, rate), 0);
144	
145	const isHighlyEnchanted = (item: Item): boolean =>
146	  (item.enchantment ?? 0) >= HIGH_ENCHANTMENT_LEVEL;
147	
148	/** Which item-specific modifiers an item attracts, by its own attributes. */
149	const ratesForItem = (item: Item): Rate[] => [
150	  ...(item.cursed ? [CURSE_SURCHARGE] : []),
151	  ...(isHighlyEnchanted(item) ? [HIGH_ENCHANTMENT_SURCHARGE] : []),
152	];
153	
154	const isLongStanding = (standing: CustomerStanding): boolean =>
155	  standing.customer.yearsWithMHPCO >= LOYALTY_YEARS;
156	
157	const holdsAnEarlierQuote = (standing: CustomerStanding): boolean => standing.quotesSoFar > 0;
158	
159	/** Which policy-wide modifiers a policy attracts, by the customer's standing. */
160	const ratesForPolicy = (standing: CustomerStanding): Rate[] => [
161	  FIRST_INSURANCE_SURCHARGE,
162	  ...(isLongStanding(standing) ? [LOYALTY_DISCOUNT] : []),
163	  ...(holdsAnEarlierQuote(standing) ? [FOLLOW_UP_DISCOUNT] : []),
164	];
165	
166	/** Item-specific modifiers apply to the affected item's own base premium. */
167	const sumOfItemModifierAmounts = (items: Item[]): number =>
168	  items.reduce(
169	    (total, item) =>
170	      total + sumOfRateAmounts(toSubunits(basePremiumOf(item)), ratesForItem(item)),
171	    0,
172	  );
173	
174	/**
175	 * Modifiers are additive amounts, each computed against its own base: item
176	 * modifiers against the affected item, policy-wide modifiers against the
177	 * policy base premium. The processing fee is added at the very end.
178	 */
179	const quotePremium = (items: Item[], standing: CustomerStanding): number => {
180	  const policyBase = toSubunits(policyBasePremiumOf(items));
181	
182	  return toPremiumGold(
183	    policyBase +
184	      sumOfItemModifierAmounts(items) +
185	      sumOfRateAmounts(policyBase, ratesForPolicy(standing)) +
186	      toSubunits(PROCESSING_FEE),
187	  );
188	};
189	
190	/**
191	 * Steps are processed in order, since a step's result can depend on those
192	 * before it — a quote is discounted once the customer holds an earlier one.
193	 */
194	export const runScenario = (scenario: Scenario): ScenarioResults => {
195	  const results: QuoteResult[] = [];
196	  let quotesSoFar = 0;
197	
198	  for (const step of scenario.steps) {
199	    const standing: CustomerStanding = { customer: scenario.customer, quotesSoFar };
200	    results.push({ premium: quotePremium(step.items, standing) });
201	    quotesSoFar += 1;
202	  }
203	
204	  return { results };
205	};
